import{_ as s,c as t,o as n,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"坎下艮上 蒙：","description":"京氏易传 - 坎下艮上 蒙：","frontmatter":{"title":"坎下艮上 蒙：","description":"京氏易传 - 坎下艮上 蒙："},"headers":[],"relativePath":"zh/classics/jingshi/054.md","filePath":"zh/classics/jingshi/054.md"}'),r={name:"zh/classics/jingshi/054.md"};function l(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"坎下艮上-蒙",tabindex:"-1"},[i("坎下艮上 蒙： "),e("a",{class:"header-anchor",href:"#坎下艮上-蒙","aria-label":"Permalink to “坎下艮上 蒙：”"},"​")],-1),e("p",null,"积阳居阴，止于坎陷。养纯正素，居中得位。《易》云：“山下出泉，蒙”。（虎易注：此句出象辞。）二象摽正，天下通也。击暗释疑，阳道行也；内实外正，暗得明，阴附于阳，稚道亨也。故曰：“蒙养正”。与艮为飞伏。【丙戌土，乙酉金。】（虎易注：乙酉金当为己酉金之误。）诸位立世，（虎易注：诸位当是诸侯之误。）元士为应。【六四，初六。】",-1),e("p",null,"建始壬子至丁巳，【大雪，小满。】积算起丁巳至丙辰，周而复始。火土入艮坎。【火土二象入卦同算。】",-1),e("p",null,"五星从位起太阴，【水星北方，入宫起算。】胃宿从位降丙戌土，【二十八宿，分胃宿入蒙卦六四丙戌土上。】分气候三十六。【起数二十八，从六位推算。】（虎易注：二十八当为三十六之误。）",-1),e("p",null,"山下见水，畜聚居中，分流万派，六位不居，吉凶适变，水土分也。【五行入卦算吉凶，逐四时行囚废王，吉则王，凶则废。】【虎易注：王通旺之义。】阴阳进退，岁时物也。六五阳中积阴，入巽见阴中阳，二气相荡，不可盈望。次降入风水涣卦。【六五变入九五，阳中阴入阳中阳，适变往于他宫，位不出本宫。】",-1)])])}const f=s(r,[["render",l]]);export{_ as __pageData,f as default};
